#include <sycl/sycl.hpp>
#include <sycl/syclcpp.hpp>

using namespace sycl;
using namespace syclcpp;

int main() {
    // Create a SYCL queue
    queue q;

    // Create a device USM allocation for weights
    usm::device_buffer d_weights(q);

    // Create a host buffer for weights
    usm::host_buffer h_weights;

    // Copy host buffer to device USM allocation
    q.submit([&](handler &h) {
        auto weights = h.template get_access<access::mode::read_write>(d_weights);
        h.copy_to_host(h_weights);
    });

    // Create a compute kernel to process the weights
    auto process_weights = hsm::kernel<process_weights>(q);

    // Submit the compute kernel to the queue
    q.submit([&](handler &h) {
        auto weights = h.template get_access<access::mode::read_write>(d_weights);
        h.submit([&](handler &h) {
            h.parallel_for<class process_weights>(weights, process_weights);
        });
    });

    // Wait for the compute kernel to complete
    q.wait();

    return 0;
}
